
package com.example.demo.domain;

import jakarta.persistence.*;
import lombok.Getter;
import lombok.Setter;

import java.math.BigDecimal;
import java.time.LocalDate;

// This class represents the payment_schedule table in MySQL
@Entity
@Table(name = "payment_schedule")
@Getter
@Setter
public class PaymentSchedule {

    // Primary key, automatically generated by MySQL
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    @Column(name = "schedule_id")
    private Integer scheduleId;

    // Each payment schedule belongs to one loan
    @OneToOne(fetch = FetchType.EAGER)
    @JoinColumn(name = "loan_id", nullable = false, unique = true)
    private Loan loan;

    // How often payments occur: MONTHLY, BIWEEKLY, or WEEKLY
    @Column(name = "frequency", nullable = false, length = 20)
    private String frequency;

    // Amount scheduled for each payment
    @Column(name = "payment_amount", nullable = false,
            precision = 12, scale = 2)
    private BigDecimal paymentAmount;

    // Date of the next scheduled payment
    @Column(name = "next_payment_date")
    private LocalDate nextPaymentDate;
}
